draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // sun
  ctx.fillStyle = 'yellow';
  ctx.beginPath();
  ctx.arc(W / 2, H / 2 - 200, 100, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // clouds
  ctx.fillStyle = 'white';
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.arc(W / 2 + Math.sin(t + i) * 200, H / 2 - 150 + Math.cos(t + i) * 50, 20 + Math.sin(t + i * 2) * 10, 0, 2 * Math.PI);
    ctx.fill();
    ctx.stroke();
  }

  // mountains
  ctx.fillStyle = 'gray';
  ctx.beginPath();
  ctx.moveTo(0, H);
  ctx.lineTo(W / 2 + Math.sin(t) * 100, H - 200);
  ctx.lineTo(W, H);
  ctx.fill();
  ctx.stroke();

  // tree
  ctx.fillStyle = 'green';
  ctx.beginPath();
  ctx.arc(W / 2, H - 100, 50, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2, H - 100);
  ctx.lineTo(W / 2, H - 50);
  ctx.stroke();

  ctx.restore();
}
